    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.commonSignalPathEClass, source, new String[]{"documentation", "The CommonSignalPath describes that two or more SwcToSwcSignals and/or SwcToSwcOperationArguments must take the same way (Signal Path) in the topology. "});
        this.addAnnotation((ENamedElement)this.getCommonSignalPath_Operations(), source, new String[]{"documentation", "\r\n "});
        this.addAnnotation((ENamedElement)this.getCommonSignalPath_Signals(), source, new String[]{"documentation", "The SwcToSwcSignals that must take the same way (Signal Path) in the topology."});
        this.addAnnotation((ENamedElement)this.swcToSwcSignalEClass, source, new String[]{"documentation", "The SwcToSwcSignal describes the information (data element) that is exchanged between two SW Components. On the SWC Level it is possible that a SW Component sends one data element from one P-Port to two different SW Components (1:n Communication). The SwcToSwcSignal describes exactly the information which is exchanged between one P-Port of a SW Component and one R-Port of another SW Component."});
        this.addAnnotation((ENamedElement)this.getSwcToSwcSignal_DataElements(), source, new String[]{"documentation", "Reference to a data element on the PPort and to the same data element on the RPort. \r\nReference to a data element on the PPort and to the same data element on the RPort. \r\nReference to a data element on the PPort and to the same data element on the RPort. "});
        this.addAnnotation((ENamedElement)this.swcToSwcOperationArgumentsEClass, source, new String[]{"documentation", "The SwcToSwcOperationArguments describes the information (client server operation arguments, plus the operation identification, if required) that are exchanged between two SW Components from exactly one client to one server, or from one server back to one client. The direction attribute defines which direction is described. If direction == IN, all arguments sent from the client to the server are described by the SwcToSwcOperationArguments, in direction == OUT, it's the arguments sent back from server to client."});
        this.addAnnotation((ENamedElement)this.getSwcToSwcOperationArguments_Direction(), source, new String[]{"documentation", "direction addressed by this SwcToSwcClientServerOperation element."});
        this.addAnnotation((ENamedElement)this.getSwcToSwcOperationArguments_Operations(), source, new String[]{"documentation", "Reference to the operation at the client and at the server side whose arguments are described by SwcToSwcOperationArguments. The two ports referenced must be connected by a connector in the software component description."});
        this.addAnnotation((ENamedElement)this.swcToSwcOperationArgumentsDirectionEnumEEnum, source, new String[]{"documentation", "direction addressed by this  element. "});
        this.addAnnotation((ENamedElement)this.swcToSwcOperationArgumentsDirectionEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "IN (all IN and INOUT arguments) "});
        this.addAnnotation((ENamedElement)this.swcToSwcOperationArgumentsDirectionEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "OUT (all OUT and INOUT arguments) ."});
        this.addAnnotation((ENamedElement)this.forbiddenSignalPathEClass, source, new String[]{"documentation", "The ForbiddenSignalPath describes the physical channels which an element must not take in the topology. Such a signal path can be a constraint for the communication matrix,  because such a path has an effect on the frame generation and the frame path.   "});
        this.addAnnotation((ENamedElement)this.getForbiddenSignalPath_Operations(), source, new String[]{"documentation", "Reference to the operation arguments of one operation which must not take the predefined way in the topology. "});
        this.addAnnotation((ENamedElement)this.getForbiddenSignalPath_PhysicalChannels(), source, new String[]{"documentation", "The SwcToSwcSignal must not be transmitted on one of these physical channels. "});
        this.addAnnotation((ENamedElement)this.getForbiddenSignalPath_Signals(), source, new String[]{"documentation", "The data element which must not take the predefined way in the topology. "});
        this.addAnnotation((ENamedElement)this.permissibleSignalPathEClass, source, new String[]{"documentation", "The PermissibleSignalPath describes the way a data element shall take in the topology. The path is described by ordered references to PhysicalChannels. \r\n\r\nIf more than one PermissibleSignalPath is defined for the same\r\nsignal/operation attributes, any of them can be chosen. Such a signal path can be a constraint for the communication matrix . This path describes that one data element should take path A (e.g. 1. Can channel, 2. Lin channel) \r\nand not path B (1. Can channel, FlexRay channel A). \r\n\r\nThis has an effect on the frame generation and the frame path.\r\n"});
        this.addAnnotation((ENamedElement)this.getPermissibleSignalPath_Operations(), source, new String[]{"documentation", "The arguments of an operation that can take the predefined way in the topology."});
        this.addAnnotation((ENamedElement)this.getPermissibleSignalPath_PhysicalChannels(), source, new String[]{"documentation", "The SwcToSwcSignal can be transmitted on one of these physical channels. "});
        this.addAnnotation((ENamedElement)this.getPermissibleSignalPath_Signals(), source, new String[]{"documentation", "The data element which can take the predefined way in the topology. "});
        this.addAnnotation((ENamedElement)this.separateSignalPathEClass, source, new String[]{"documentation", "The SeparateSignalPath describes that two SwcToSwcSignals and/or SwcToSwcOperationArguments must not take the same way (Signal Path) in the topology (e.g. Redundancy).\r\n"});
        this.addAnnotation((ENamedElement)this.getSeparateSignalPath_Operations(), source, new String[]{"documentation", "The SwcToSwcOperationArguments that must not take the same way (Signal Path) in the topology."});
        this.addAnnotation((ENamedElement)this.getSeparateSignalPath_Signals(), source, new String[]{"documentation", "The SwcToSwcSignals that must not take the same way (Signal Path) in the topology."});
        this.addAnnotation((ENamedElement)this.signalPathConstraintEClass, source, new String[]{"documentation", "Additional guidelines for the System Generator, which specific way a signal between two Software Components should take in the network without defining in which frame and with which timing it is transmitted."});
    }

